-void Assembler::evfmadd132ph(XMMRegister dst, XMMRegister nds, Address src, int vector_len) {
-  assert(VM_Version::supports_avx512_fp16(), "");
-  assert(vector_len == Assembler::AVX_512bit || VM_Version::supports_avx512vl(), "");
